	// Country Subdivisions
	function CountrySubDivision(strCountryISO3, strSubDivisionCode, strName, strNameEN)
	{
		strNameEN = x_snc_devtools.GetStringValue(strNameEN);
		if (strNameEN == '')
		{
			strNameEN = strName;
		}
		var grCountry = x_snc_devtools.GetCountryRecord(strCountryISO3);
		if (x_snc_devtools.IsValidRecord(grCountry) == false)
		{
			installer.Error('Country not found by ISO3 code: '+strCountryISO3);
			return false;
		}
		installer.RecordInsertOrUpdate('Adding/Updating subdivision for ' + grCountry.name+': ' + strName,
			'x_snc_geodata_country_subdivision',
			{
				country: grCountry.sys_id,
				iso_3166_2_code: strSubDivisionCode
			},
			{
				name: strName,
				name_en: strNameEN
			},
			{
				level: 1
			});		

	}


